// Calcula el rango a consultar en hora de MEXICO (UTC-6 fijo).
//
// OJO: el comando se saca del MENSAJE, no de un campo `comando`. El Router
// enruta por el texto y no añade campos; leer item.comando devolvía
// undefined y todo caía en 'HOY' por defecto.
const TZ = 'America/Mexico_City';
const item = $input.first().json;
const texto = String(item.message_content || '').trim();
const comando = (texto.split(/\s+/)[0] || 'HOY').toUpperCase();

function fechaMexico(d) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(d);
}
function sumarDias(f, n) {
  const [a, m, dd] = f.split('-').map(Number);
  const t = Date.UTC(a, m - 1, dd) + n * 86400000;
  const g = new Date(t);
  return `${g.getUTCFullYear()}-${String(g.getUTCMonth() + 1).padStart(2, '0')}-${String(g.getUTCDate()).padStart(2, '0')}`;
}
const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
function fechaCorta(f) {
  const [a, m, dd] = f.split('-').map(Number);
  const wd = new Date(Date.UTC(a, m - 1, dd)).getUTCDay();
  return `${DIAS[wd]} ${dd} de ${MESES[m - 1]}`;
}

const ahora = new Date();
const hoy = fechaMexico(ahora);
let desde = hoy, hasta = hoy, titulo = '';

if (comando === 'SEMANA') {
  hasta = sumarDias(hoy, 7);
  titulo = `los próximos 7 días (desde ${fechaCorta(hoy)})`;
} else if (comando === 'LIBRE') {
  hasta = sumarDias(hoy, 2);
  titulo = 'hoy y los siguientes 2 días';
} else if (comando === 'MAÑANA' || comando === 'MANANA') {
  desde = sumarDias(hoy, 1); hasta = desde;
  titulo = `mañana, ${fechaCorta(desde)}`;
} else if (comando === 'HOY') {
  titulo = `hoy, ${fechaCorta(hoy)}`;
} else {
  // Por si LIBRE/SEMANA llegan con otro alias
  titulo = `hoy, ${fechaCorta(hoy)}`;
}

return [{ json: {
  comando,
  desde, hasta, titulo,
  esRango: desde !== hasta,
  timeMin: `${desde}T00:00:00-06:00`,
  timeMax: `${hasta}T23:59:00-06:00`,
  ahoraISO: ahora.toISOString(),
} }];

// Arma la respuesta de WhatsApp con la agenda o los huecos.
//
// ORDEN IMPORTANTE: el comando LIBRE se evalúa PRIMERO, antes de cualquier
// comprobación sobre las citas. Antes estaba dentro del bloque de "no hay
// citas" y nunca llegaba a ejecutarse.
const TZ = 'America/Mexico_City';
const entrada = $('Preparar rango de fechas').first().json;
const todos = $input.all().map(i => i.json);

const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
               'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

function a12h(min) {
  const h = Math.floor(min / 60), m = min % 60;
  const suf = h < 12 ? 'a.m.' : 'p.m.';
  const h12 = h % 12 === 0 ? 12 : h % 12;
  return `${h12}:${String(m).padStart(2, '0')} ${suf}`;
}
function minutos(dt) {
  const m = /T(\d{2}):(\d{2})/.exec(dt || '');
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}
function fechaDe(dt) {
  const m = /^(\d{4}-\d{2}-\d{2})/.exec(dt || '');
  return m ? m[1] : null;
}
function fechaCorta(f) {
  const [a, m, dd] = f.split('-').map(Number);
  const wd = new Date(Date.UTC(a, m - 1, dd)).getUTCDay();
  return `${DIAS[wd]} ${dd} de ${MESES[m - 1]}`;
}
function sumarDias(f, n) {
  const [a, m, dd] = f.split('-').map(Number);
  const t = Date.UTC(a, m - 1, dd) + n * 86400000;
  const g = new Date(t);
  return `${g.getUTCFullYear()}-${String(g.getUTCMonth() + 1).padStart(2, '0')}-${String(g.getUTCDate()).padStart(2, '0')}`;
}
function nombreCliente(e) {
  const m = /Nombre:\s*([^\n]+)/i.exec(e.desc);
  if (m) return m[1].trim();
  const partes = e.resumen.split(/\s+[—–-]\s+/);
  return partes.length > 1 ? partes[partes.length - 1].trim() : e.resumen;
}
function servicio(e) {
  const partes = e.resumen.split(/\s+[—–-]\s+/);
  return partes.length > 1 ? partes[0].trim() : '';
}
function precio(e) {
  const m = /\$\s*(\d+)|Precio\s*:\s*(\d+)/i.exec(e.desc);
  return m ? Number(m[1] || m[2]) : null;
}

// Normaliza los eventos del calendario
const eventos = todos.filter(e => e && (e.summary || e.start))
  .map(e => {
    const dt = e.start ? (e.start.dateTime || e.start.date || '') : '';
    return {
      ini: e.start && e.start.date && !e.start.dateTime ? -1 : minutos(dt),
      fin: e.end ? minutos(e.end.dateTime || e.end.date || '') : null,
      fecha: fechaDe(dt),
      resumen: e.summary || '',
      desc: e.description || '',
    };
  })
  .filter(e => e.ini !== null && e.ini >= 0 && e.fecha)
  .sort((a, b) => (a.fecha + String(a.ini).padStart(4, '0'))
        .localeCompare(b.fecha + String(b.ini).padStart(4, '0')));

const ahora = new Date(entrada.ahoraISO);
const AHOY = new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(ahora);
const pA = {};
for (const { type, value } of new Intl.DateTimeFormat('en-CA',
  { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false })
  .formatToParts(ahora)) pA[type] = value;
const ahoraMin = Number(pA.hour === '24' ? '0' : pA.hour) * 60 + Number(pA.minute);

// ------------------------------------------------------------------
// 1. LIBRE -> huecos disponibles. PRIMERO, siempre.
// ------------------------------------------------------------------
if (entrada.comando === 'LIBRE') {
  const dur = 40;                      // duración de referencia
  const AP = 10 * 60, CI = 20 * 60;    // 10:00 a 20:00
  const porFecha = {};
  for (const e of eventos) (porFecha[e.fecha] = porFecha[e.fecha] || []).push(e);

  const l = [`*Huecos disponibles (${dur} min)*`];
  let total = 0;

  for (let f = entrada.desde; f <= entrada.hasta; f = sumarDias(f, 1)) {
    const dow = new Date(f + 'T12:00:00Z').getUTCDay();
    if (dow === 0) continue;                       // domingo, cerrado
    const ocupados = porFecha[f] || [];
    const libres = [];
    for (let t = AP; t + dur <= CI; t += 30) {
      const fin = t + dur;
      const choca = ocupados.some(e => e.fin !== null &&
        t < e.fin + 10 && e.ini - 10 < fin);
      if (choca) continue;
      if (f === AHOY && t <= ahoraMin) continue;
      libres.push(t);
      if (libres.length >= 8) break;
    }
    total += libres.length;
    l.push('');
    l.push(`*${f === AHOY ? 'Hoy' : fechaCorta(f)}*`);
    l.push(libres.length ? libres.map(a12h).join(', ') : 'Sin huecos libres.');
  }

  l.push('');
  l.push(total ? `Total: *${total} huecos* disponibles.`
               : 'No hay huecos en el periodo.');
  return [{ json: { respuesta: l.join('\n') } }];
}

// ------------------------------------------------------------------
// 2. Sin citas -> decirlo
// ------------------------------------------------------------------
const lineas = [`*Agenda de ${entrada.titulo}*`];
if (!eventos.length) {
  lineas.push('');
  lineas.push('No hay citas agendadas en ese periodo.');
  return [{ json: { respuesta: lineas.join('\n') } }];
}

// ------------------------------------------------------------------
// 3. Rango de varios días -> agrupar por día
// ------------------------------------------------------------------
if (entrada.esRango) {
  const porDia = {};
  for (const e of eventos) (porDia[e.fecha] = porDia[e.fecha] || []).push(e);
  let totalP = 0, conPrecio = 0;
  for (const f of Object.keys(porDia).sort()) {
    lineas.push('');
    lineas.push(`*${fechaCorta(f)}*`);
    for (const e of porDia[f]) {
      const pr = precio(e);
      if (pr !== null) { totalP += pr; conPrecio++; }
      let x = `${a12h(e.ini)} ${nombreCliente(e)}`;
      const sv = servicio(e);
      if (sv) x += ` — ${sv}`;
      lineas.push(x);
    }
  }
  lineas.push('');
  lineas.push(`*${eventos.length} cita${eventos.length === 1 ? '' : 's'} en el periodo` +
    (conPrecio ? ` · $${totalP} estimado` : '') + '*');
  return [{ json: { respuesta: lineas.join('\n') } }];
}

// ------------------------------------------------------------------
// 4. Un solo día -> lista + huecos
// ------------------------------------------------------------------
let totalD = 0, conP = 0;
for (const e of eventos) {
  const pr = precio(e);
  if (pr !== null) { totalD += pr; conP++; }
  let x = `${a12h(e.ini)} ${nombreCliente(e)}`;
  const sv = servicio(e);
  if (sv) x += ` — ${sv}`;
  if (pr !== null) x += ` · $${pr}`;
  lineas.push(x);
}
lineas.push('');
lineas.push(`*${eventos.length} cita${eventos.length === 1 ? '' : 's'}` +
  (conP ? ` · $${totalD} estimado` : '') + '*');

const dur2 = 40, libres2 = [];
for (let t = 600; t + dur2 <= 1200; t += 30) {
  const fin = t + dur2;
  const choca = eventos.some(e => e.fin !== null &&
    t < e.fin + 10 && e.ini - 10 < fin);
  if (choca) continue;
  if (entrada.desde === AHOY && t <= ahoraMin) continue;
  libres2.push(t);
  if (libres2.length >= 6) break;
}
lineas.push(libres2.length
  ? `Huecos: ${libres2.map(a12h).join(', ')}`
  : 'Sin huecos disponibles ese día.');

return [{ json: { respuesta: lineas.join('\n') } }];

// Interpreta BLOQUEAR / CERRAR / ABRIR y prepara el evento de Calendar.
const item = $input.first().json;
const texto = String(item.message_content || '').trim();
const partes = texto.split(/\s+/);
const comando = (partes[0] || '').toUpperCase();
const resto = partes.slice(1);

const TZ = 'America/Mexico_City';
function fechaMexico(d) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(d);
}
function sumarDias(f, n) {
  const [a, m, dd] = f.split('-').map(Number);
  const t = Date.UTC(a, m - 1, dd) + n * 86400000;
  const g = new Date(t);
  return `${g.getUTCFullYear()}-${String(g.getUTCMonth() + 1).padStart(2, '0')}-${String(g.getUTCDate()).padStart(2, '0')}`;
}
const MESES = { ene: 1, feb: 2, mar: 3, abr: 4, may: 5, jun: 6,
                jul: 7, ago: 8, sep: 9, oct: 10, nov: 11, dic: 12 };
const ahora = new Date();
const hoy = fechaMexico(ahora);

function fallo(msg) {
  return [{ json: { ...item, respuesta: msg, saltar: true } }];
}

if (comando === 'BLOQUEAR') {
  let fecha = hoy, idx = 0;
  if (resto[0] && /^\d{4}-\d{2}-\d{2}$/.test(resto[0])) { fecha = resto[0]; idx = 1; }
  const rango = resto[idx];
  if (!rango || !/^\d{1,2}:\d{2}-\d{1,2}:\d{2}$/.test(rango)) {
    return fallo('Formato: *BLOQUEAR 14:00-15:30 motivo*');
  }
  const [d, h] = rango.split('-');
  const aMin = s => { const [a, b] = s.split(':').map(Number); return a * 60 + b; };
  if (aMin(h) <= aMin(d)) {
    return fallo('La hora final debe ser mayor que la inicial.');
  }
  const motivo = resto.slice(idx + 1).join(' ') || 'ocupado';
  return [{ json: { ...item, comando, saltar: false, accion: 'crear',
    fecha, inicioISO: `${fecha}T${d.padStart(5, '0')}:00-06:00`,
    finISO: `${fecha}T${h.padStart(5, '0')}:00-06:00`,
    summary: `Bloqueado: ${motivo}`,
    description: 'Bloqueo creado por el dueño desde WhatsApp',
    ok_msg: `Listo. Bloqueé *${d} a ${h}* (${motivo}).` } }];
}

if (comando === 'CERRAR' || comando === 'ABRIR') {
  const arg = resto.join(' ').trim();
  if (!arg) return fallo(`Formato: *${comando} 24 dic*`);
  let fecha = null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(arg)) fecha = arg;
  else if (/^hoy$/i.test(arg)) fecha = hoy;
  else if (/^mañana$/i.test(arg)) fecha = sumarDias(hoy, 1);
  else {
    const m = /^(\d{1,2})\s+([a-záéíóú]{3,})$/i.exec(arg);
    if (m) {
      const mes = MESES[m[2].slice(0, 3).toLowerCase()];
      const dia = Number(m[1]);
      if (mes) {
        const p = {};
        for (const { type, value } of new Intl.DateTimeFormat('en-CA',
          { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' })
          .formatToParts(ahora)) p[type] = value;
        let anio = Number(p.year);
        if (mes < Number(p.month) || (mes === Number(p.month) && dia < Number(p.day))) anio++;
        fecha = `${anio}-${String(mes).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
      }
    }
  }
  if (!fecha) return fallo('No entendí la fecha. Ejemplo: *CERRAR 24 dic*');
  const esCerrar = comando === 'CERRAR';
  return [{ json: { ...item, comando, saltar: false, accion: 'crear',
    fecha,
    inicioISO: `${fecha}T00:00:00-06:00`,
    finISO: `${fecha}T23:59:00-06:00`,
    summary: esCerrar ? 'CERRADO' : 'ABIERTO',
    description: esCerrar ? 'Día cerrado desde WhatsApp' : 'Día reabierto desde WhatsApp',
    ok_msg: esCerrar
      ? `Listo. Marqué el *${fecha}* como cerrado.`
      : `Listo. El *${fecha}* vuelve a estar abierto.` } }];
}

return fallo('Comando de bloqueo no reconocido.');

// Extrae el numero a buscar del comando CLIENTE.
const item = $input.first().json;
const partes = String(item.message_content || '').trim().split(/\s+/);
const busqueda = (partes[1] || '').replace(/\D/g, '');
return [{ json: { ...item, busqueda, busquedaOk: busqueda.length >= 6 } }];

// Arma la ficha del cliente en formato WhatsApp.
const item = $('Buscar cliente').first().json;
const filas = $input.all().map(i => i.json).filter(f => f && f.nombre);

if (!item.busquedaOk) {
  return [{ json: { respuesta: 'Formato: *CLIENTE 4521206246*' } }];
}
if (!filas.length) {
  return [{ json: { respuesta: `No encontré ninguna ficha para el *${item.busqueda}*.\n\nEse número no ha agendado con nosotros.` } }];
}
const c = filas[0];
const l = [`*${c.nombre}*`];
if (c.etiqueta) l.push(`Etiqueta: ${c.etiqueta}`);
l.push(`Visitas: ${c.visitas || 0}`);
if (Number(c.no_shows) > 0) l.push(`No-shows: ${c.no_shows}`);
if (c.ticket_promedio) l.push(`Ticket promedio: $${Math.round(c.ticket_promedio)}`);
if (c.servicio_habitual) l.push(`Suele pedir: ${c.servicio_habitual}`);
if (c.ultima) l.push(`Última visita: ${c.ultima}`);
l.push(`Citas próximas: ${c.futuras || 0}`);
if (c.nota_interna) l.push(`Nota: ${c.nota_interna}`);
return [{ json: { respuesta: l.join('\n') } }];

// PAUSA 4521206246 2h  ->  deja de contestarle ese cliente.
const item = $input.first().json;
const partes = String(item.message_content || '').trim().split(/\s+/);
const numero = (partes[1] || '').replace(/\D/g, '');
const horasTxt = (partes[2] || '').toLowerCase();
const m = /^(\d{1,2})h?$/.exec(horasTxt);
const horas = m ? Number(m[1]) : null;

if (numero.length < 6 || horas === null || horas <= 0 || horas > 72) {
  return [{ json: { ...item, pausaOk: false,
    respuesta: 'Formato: *PAUSA 4521206246 2h* (de 1 a 72 horas)' } }];
}
return [{ json: { ...item, pausaOk: true, numero, horas } }];

// Confirma la pausa o avisa si el cliente no existe.
const item = $('Parsear pausa').first().json;
if (!item.pausaOk) return [{ json: { respuesta: item.respuesta } }];

const filas = $input.all().map(i => i.json).filter(f => f && f.jid);
if (!filas.length) {
  return [{ json: { respuesta: `No encontré un cliente con el número *${item.numero}*.\n\nLa pausa solo aplica a clientes que ya existen en el sistema.` } }];
}
const hasta = new Date(filas[0].hasta);
const hora = new Intl.DateTimeFormat('es-MX', {
  timeZone: 'America/Mexico_City', hour: '2-digit', minute: '2-digit', hour12: true }).format(hasta);
return [{ json: { respuesta: `Pausado por *${item.horas} h*.\n\nEl bot no le contestará hasta las *${hora}*.\n\nReanuda solo.` } }];

// El comando PRECIO nunca cambia depilación (precio por zona).
const item = $input.first().json;
const partes = String(item.message_content || '').trim().split(/\s+/);
const clave = (partes[1] || '').toLowerCase();
const precio = Number(partes[2]);
const duracion = partes[3] === undefined ? null : Number(partes[3]);
const validos = new Set(['corte','barba','ceja','mascarilla','dama','planchado','peinado']);
if (!validos.has(clave) || !/^\d+(?:\.\d{1,2})?$/.test(partes[2] || '') || !Number.isFinite(precio) || precio <= 0 ||
    (duracion !== null && (!Number.isInteger(duracion) || duracion <= 0))) {
  return [{ json: { ...item, precioOk: false,
    respuesta: clave === 'depilacion' ? 'La depilación se cobra según la zona; consulta el precio con el encargado.' : 'Formato: *PRECIO ceja 40*. El servicio debe existir y el precio ser mayor a cero.' } }];
}
return [{ json: { ...item, precioOk: true, clave, precio, duracion } }];

// Confirma el cambio de precio, o lista el catálogo si la clave no existe.
const item = $('Parsear precio').first().json;
const filas = $input.all().map(i => i.json).filter(f => f && f.clave);

if (!item.precioOk) return [{ json: { respuesta: item.respuesta } }];
if (!filas.length) {
  return [{ json: { respuesta: `No tengo un servicio con la clave *${item.clave}*.\n\nClaves válidas: corte, barba, ceja, mascarilla, dama, planchado, peinado, depilacion.` } }];
}
const s = filas[0];
let r = `Listo. *${s.nombre}* ahora cuesta *$${Math.round(s.precio)}*.`;
if (s.duracion_min) r += `\nDuración: ${s.duracion_min} min.`;
return [{ json: { respuesta: r } }];

// Salud del sistema en formato WhatsApp.
const e = $input.first().json;
const l = ['*Estado del sistema*', ''];
l.push(`Citas hoy: ${e.citas_hoy || 0}`);
l.push(`Citas esta semana: ${e.citas_semana || 0}`);
l.push(`Escalaciones abiertas: ${e.escalaciones || 0}`);
l.push(`Pausas activas: ${e.pausas || 0}`);
l.push(`Operadores: ${e.operadores || 0}`);
l.push('');
l.push('Bot activo ✅');
return [{ json: { respuesta: l.join('\n') } }];

// ¿El remitente es un operador autorizado?
// Compara por los ÚLTIMOS 10 dígitos para tolerar los dos formatos
// mexicanos de WhatsApp (52+10 y 52+1+10).
const item = $('Normalizacion').first().json;
const remitente = String(item.user_number || '');
const ultimos = s => String(s || '').replace(/\D/g, '').slice(-10);

const autorizados = $input.all()
  .map(i => i.json.jid)
  .filter(Boolean);

const esOperador = autorizados.some(j => ultimos(j) === ultimos(remitente));

return [{ json: { ...item, es_operador: esOperador,
                  operadores: autorizados } }];

// Decide si hay que quedarse callado con este cliente.
// La consulta devuelve count(*) = 0 o 1 y SIEMPRE una fila, así que el
// flujo no se corta cuando el cliente no está pausado.
const base = $('Normalizacion').first().json;
const fila = $input.first().json || {};
const pausado = Number(fila.pausado || 0) > 0;
return [{ json: { ...base, pausado, hasta: fila.hasta || null } }];

// Una fila JSON agregada evita perder el mensaje del cliente al consultar múltiples servicios.
const raw = $input.first()?.json?.catalogo;
let rows;
try { rows = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch { throw new Error('Catálogo de servicios inválido'); }
if (!Array.isArray(rows) || !rows.length) throw new Error('Catálogo vacío; no se permite cotizar');
const seen = new Set();
for (const r of rows) {
  if (!r || typeof r.clave !== 'string' || !/^[a-z0-9_]+$/.test(r.clave) ||
      seen.has(r.clave) || typeof r.nombre !== 'string' || !r.nombre.trim() ||
      !Number.isInteger(Number(r.duracion_min)) || Number(r.duracion_min) <= 0 ||
      r.precio === null || r.precio === '' || !Number.isFinite(Number(r.precio)) ||
      (r.clave === 'depilacion' ? Number(r.precio) !== 0 : Number(r.precio) <= 0)) {
    throw new Error('Catálogo inválido o precio no válido; no se permite cotizar');
  }
  seen.add(r.clave);
}
const lines = rows.map(r => `- ${r.nombre}: ${r.clave === 'depilacion' ? 'precio según la zona' : '$' + Number(r.precio).toFixed(2).replace(/\.00$/, '')} (${r.duracion_min} min)`);
return [{ json: { chat_input: $('Edit Fields').first().json.chat_input, catalogo_texto: lines.join('\n') } }];
